// Joins each due post to its row in the Channels table and decides how to publish it.
// Field names follow docs/data-model.md. One output item per post.
const config = $('Config').first().json;

// Airtable node v2.1 flattens fields onto the item. v2.2+ keeps them under `fields`. Handle both.
const rows = (items) => items
  .map((i) => i.json)
  .filter((j) => j && j.id)
  .map((j) => ({ id: j.id, ...(j.fields ?? j) }));

const posts = rows($('Search due posts').all());
const channels = rows($('List channels').all());
const channelByName = new Map(channels.map((c) => [String(c['Name'] ?? '').trim().toLowerCase(), c]));

const NEEDS_MEDIA = ['instagram', 'tiktok', 'youtube', 'pinterest']; // no text-only posts
const NEEDS_TARGET = ['pinterest', 'reddit'];                         // board / subreddit required
const TARGET_FIELD = {                                               // where Target ID goes
  linkedin: 'target_linkedin_page_id',
  facebook: 'facebook_page_id',
  pinterest: 'pinterest_board_id',
  reddit: 'subreddit',
};
const MANUAL_PLATFORMS = ['substack', 'other'];

// Upload-Post wants multipart/form-data with repeated fields (platform[], photos[]).
// The HTTP Request node can't repeat a field a variable number of times, so the body is built here.
function multipart(fields) {
  const boundary = '----agentSocialCalendar' + Date.now().toString(16) + Math.random().toString(16).slice(2);
  let body = '';
  for (const [name, value] of fields) {
    body += `--${boundary}\r\nContent-Disposition: form-data; name="${name}"\r\n\r\n${value}\r\n`;
  }
  body += `--${boundary}--\r\n`;
  return { contentType: `multipart/form-data; boundary=${boundary}`, body };
}

const out = [];
let skippedInactive = 0;

for (const p of posts) {
  if (config.onlyRecordId && p.id !== config.onlyRecordId) continue;

  const channelName = String(p['Channel'] ?? '').trim();
  const media = Array.isArray(p['Media']) ? p['Media'] : [];
  const video = media.find((m) => String(m.type ?? '').startsWith('video/'));
  const mediaType = media.length === 0 ? 'text' : video ? 'video' : 'photo';
  const text = String(p['PostContent'] ?? '').trim();

  const item = {
    recordId: p.id,
    name: p['Name'] ?? '',
    channel: channelName,
    scheduledFor: p['Scheduled for'] ?? '',
    text,
    mediaType,
    // Airtable attachment URLs expire after a few hours. These were fetched seconds ago.
    mediaUrls: video ? [video.url] : media.map((m) => m.url),
    platform: '',
    action: '',
    error: '',
  };
  const fail = (message) => {
    item.action = 'invalid';
    item.error = message;
    out.push({ json: item });
  };

  const ch = channelByName.get(channelName.toLowerCase());
  if (!ch) { fail(`Channel "${channelName}" is not in the Channels table. The names must match exactly.`); continue; }
  if (!ch['Active']) { skippedInactive++; continue; } // inactive channels are skipped and stay Approved

  const platform = String(ch['Platform'] ?? '').trim().toLowerCase();
  item.platform = platform;

  if (ch['Manual'] || MANUAL_PLATFORMS.includes(platform)) {
    item.action = 'manual';
    item.slackText = `*Post this by hand on ${channelName}* (${item.name})\n\n${text}` +
      (item.mediaUrls.length ? `\n\nMedia (these links expire in a few hours):\n${item.mediaUrls.join('\n')}` : '') +
      `\n\nThe record is marked Manual in Airtable. Paste the live link there once it's up.`;
    out.push({ json: item });
    continue;
  }

  if (!text && media.length === 0) { fail('PostContent and Media are both empty.'); continue; }
  if (mediaType === 'text' && NEEDS_MEDIA.includes(platform)) { fail(`${platform} does not accept text-only posts. Add an image or video to Media.`); continue; }
  if (mediaType === 'photo' && platform === 'youtube') { fail('YouTube only takes video.'); continue; }

  const user = String(ch['Upload-Post user'] ?? '').trim();
  if (!user) { fail(`Channel "${channelName}" has no Upload-Post user.`); continue; }

  const targetId = String(ch['Target ID'] ?? '').trim();
  if (NEEDS_TARGET.includes(platform) && !targetId) { fail(`${platform} needs a Target ID on the channel (board ID or subreddit).`); continue; }

  const fields = [['user', user], ['platform[]', platform]];
  if (text) fields.push(['title', text]);
  if (targetId && TARGET_FIELD[platform]) fields.push([TARGET_FIELD[platform], targetId]);
  if (mediaType === 'photo') for (const url of item.mediaUrls) fields.push(['photos[]', url]);
  if (mediaType === 'video') fields.push(['video', item.mediaUrls[0]]);

  // Optional: hold the post until the channel's Post time. Upload-Post keeps it and returns a job_id.
  if (config.usePostTime) {
    const tz = String(ch['Timezone'] || config.timezone);
    const time = String(ch['Post time'] ?? '').trim();
    if (/^\d{1,2}:\d{2}$/.test(time) && item.scheduledFor) {
      const at = DateTime.fromISO(`${item.scheduledFor}T${time.padStart(5, '0')}`, { zone: tz });
      if (at.isValid && at > DateTime.now().plus({ minutes: 5 })) {
        fields.push(['scheduled_date', at.toFormat("yyyy-MM-dd'T'HH:mm:ss")], ['timezone', tz]);
        item.scheduledAt = at.toISO();
      }
    }
  }

  item.action = mediaType;
  item.request = multipart(fields);
  out.push({ json: item });
}

if (out.length === 0) {
  return [{ json: { nothingDue: true, dueRecords: posts.length, skippedInactive } }];
}
return out;

// How many approved posts are waiting after today, and which one is next.
const upcoming = $input.all()
  .map((i) => i.json)
  .filter((j) => j && j.id)
  .map((j) => ({ id: j.id, ...(j.fields ?? j) }))
  .sort((a, b) => String(a['Scheduled for']).localeCompare(String(b['Scheduled for'])));

const next = upcoming[0];
return [{
  json: {
    queueEmpty: upcoming.length === 0,
    queued: upcoming.length,
    nextDate: next?.['Scheduled for'] ?? null,
    nextChannel: next?.['Channel'] ?? null,
    nextName: next?.['Name'] ?? null,
  },
}];

// Turns the Upload-Post response (or error) into the Airtable update for this post.
const post = $('Loop Over Items').item.json;
const res = $json;

function errorText(e) {
  if (e == null) return 'Unknown error';
  if (typeof e === 'string') return e.slice(0, 2000);
  const parts = [e.message, e.description];
  const body = e.error ?? e.response?.body ?? e.response?.data;
  if (body) parts.push(typeof body === 'string' ? body : JSON.stringify(body));
  const text = parts.filter(Boolean).join(' | ') || JSON.stringify(e);
  return text.slice(0, 2000);
}

let update;
if (post.action === 'invalid') {
  update = { Status: 'Failed', Error: post.error };
} else if (post.action === 'manual') {
  update = { Status: 'Manual', Error: '' };
} else if (res.error && res.success !== true) {
  // Error output of the HTTP node, or a 200 body that carries an error
  update = { Status: 'Failed', Error: errorText(res.error) };
} else {
  const results = res.results ?? {};
  const r = results[post.platform] ?? (post.platform === 'x' ? results.twitter : undefined) ?? Object.values(results)[0];
  if (res.success === false || r?.success === false) {
    update = { Status: 'Failed', Error: errorText(r?.error ?? res.message ?? res) };
  } else if (r?.skipped) {
    update = { Status: 'Failed', Error: `Upload-Post skipped ${post.platform}: this Upload-Post user has no ${post.platform} account connected.` };
  } else if (res.job_id) {
    // Only happens with usePostTime on: Upload-Post holds the post until the channel's Post time
    update = { Status: 'Scheduled', 'Upload-Post ID': String(res.job_id), Error: '' };
  } else {
    update = { Status: 'Live', 'Posted at': new Date().toISOString(), Error: '' };
    // Long uploads switch to background processing: you get a request_id and no link yet
    const id = res.request_id ?? r?.post_id ?? r?.publish_id ?? r?.id;
    if (id) update['Upload-Post ID'] = String(id);
    if (r?.url) update['Live link'] = r.url;
  }
}

return { json: { id: post.recordId, ...update } };

// One Slack message for the whole run. Items are the Airtable records the loop updated.
const config = $('Config').first().json;
const today = $now.setZone(config.timezone).toISODate();

const groups = { Live: [], Scheduled: [], Manual: [], Failed: [] };
let notUpdated = 0;
for (const { json } of $input.all()) {
  const r = json.fields ? { id: json.id, ...json.fields } : json;
  if (groups[r.Status]) groups[r.Status].push(r);
  else notUpdated++; // the Airtable update itself failed
}

const label = (r) => r['Name'] || r.id;
const line = (r) => `• ${r['Channel'] ?? '?'}: ${r['Live link'] ? `<${r['Live link']}|${label(r)}>` : label(r)}`;

let text = `*Social calendar, ${today}*\n` +
  `${groups.Live.length} live, ${groups.Scheduled.length} held for their post time, ` +
  `${groups.Manual.length} to post by hand, ${groups.Failed.length} failed.`;

if (groups.Live.length) text += `\n\n*Live*\n${groups.Live.map(line).join('\n')}`;
const linkedin = groups.Live.filter((r) => /linkedin/i.test(r['Channel'] ?? ''));
if (linkedin.length) text += `\n\n${linkedin.length} LinkedIn post(s) just went up. A like and a comment from the team in the first hour helps.`;
if (groups.Scheduled.length) text += `\n\n*Held until post time*\n${groups.Scheduled.map(line).join('\n')}`;
if (groups.Manual.length) text += `\n\n*Post by hand* (details sent above)\n${groups.Manual.map(line).join('\n')}`;
if (groups.Failed.length) {
  text += `\n\n*Failed*\n` + groups.Failed
    .map((r) => `${line(r)}\n    ${String(r['Error'] ?? '').slice(0, 300)}`)
    .join('\n');
}
if (notUpdated) text += `\n\n${notUpdated} record(s) could not be written back to Airtable. Check the n8n execution log.`;

return [{ json: { slackText: text } }];
